cd ~/projects/hackathons/Grasshopper/server/src && cat > gemma.ts <<'EOF'
// Gemma behind a tiny interface so the host is a config change, not a rewrite.
// Locally we talk to Ollama; a hosted provider can implement the same shape later.

export interface GemmaClient {
  /** Returns the model's raw text reply, constrained to `schema` when the host supports it. */
  generateJson(system: string, user: string, schema: object): Promise<string>;
}

const OLLAMA_URL = process.env.OLLAMA_URL ?? "http://localhost:11434";
const GEMMA_MODEL = process.env.GEMMA_MODEL ?? "gemma3:4b";

export const ollamaGemma: GemmaClient = {
  async generateJson(system, user, schema) {
    const res = await fetch(`${OLLAMA_URL}/api/chat`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        model: GEMMA_MODEL,
        stream: false,
        format: schema,
        options: { temperature: 0.9 },
        messages: [
          { role: "system", content: system },
          { role: "user", content: user },
        ],
      }),
    });
    if (!res.ok) {
      throw new Error(`Ollama ${res.status}: ${await res.text()}`);
    }
    const body = (await res.json()) as { message?: { content?: string } };
    return body.message?.content ?? "";
  },
};
EOF
cat > quests.ts <<'EOF'
import { randomUUID } from "node:crypto";
import { z } from "zod";
import type { GemmaClient } from "./gemma.js";

const QuestSchema = z.object({
  title: z.string().min(1).max(80),
  hint: z.string().min(1).max(160),
  visual: z.string().min(1).max(60),
  difficulty: z.enum(["easy", "medium", "hard"]),
});

const ResponseSchema = z.object({ quests: z.array(QuestSchema).length(5) });

export type Quest = z.infer<typeof QuestSchema> & { id: string };

const SYSTEM = `You design tiny real-world scavenger hunts for someone about to go on a short walk.
Rules for every quest:
- It is something you can spot and photograph outdoors from a public street, path or park.
- It is safe: no strangers' faces, no trespassing, no touching or chasing animals, no traffic.
- It is common enough to find within a 20-30 minute walk.
- "title" is playful, 3 to 8 words.
- "hint" is one short, friendly sentence on where to look.
- "visual" is a plain noun phrase describing what the photo will show, for an image classifier. Example: "a red door", "a cat on a wall", "a bicycle".`;

function userPrompt(place: string | undefined): string {
  const where = place
    ? `The walk is in ${place}. Make at least two quests specific to everyday street life there.`
    : "The walk is in an ordinary neighbourhood; keep quests universal.";
  return `${where}
Write exactly 5 quests ordered from easiest to hardest: 2 easy, 2 medium, 1 hard.
Return JSON: {"quests": [{"title", "hint", "visual", "difficulty"}]}.`;
}

export async function generateQuests(gemma: GemmaClient, place?: string): Promise<Quest[]> {
  const schema = z.toJSONSchema(ResponseSchema);
  const raw = await gemma.generateJson(SYSTEM, userPrompt(place), schema);
  const parsed = ResponseSchema.parse(JSON.parse(raw));
  return parsed.quests.map((q) => ({ ...q, id: randomUUID() }));
}
EOF
cat > index.ts <<'EOF'
import express from "express";
import { z } from "zod";
import { ollamaGemma } from "./gemma.js";
import { generateQuests } from "./quests.js";

const PORT = Number(process.env.PORT ?? 3001);
const app = express();
app.use(express.json());

app.get("/api/health", (_req, res) => {
  res.json({ ok: true });
});

const QuestRequest = z.object({ place: z.string().trim().max(80).optional() });

app.post("/api/quests", async (req, res) => {
  const body = QuestRequest.safeParse(req.body ?? {});
  if (!body.success) {
    res.status(400).json({ error: "place must be a short string" });
    return;
  }
  try {
    const quests = await generateQuests(ollamaGemma, body.data.place || undefined);
    res.json({ quests });
  } catch (err) {
    console.error("quest generation failed:", err);
    res.status(502).json({ error: "Gemma couldn't write quests right now. Is Ollama running?" });
  }
});

app.listen(PORT, () => {
  console.log(`grasshopper api on http://localhost:${PORT}`);
});
EOF
