  position: absolute;
  right: 12px;
  bottom: 12px;
  padding: 4px 12px;
  border: 3px solid var(--ink);
  border-radius: 8px;
  background: var(--lime);
  font: 14px var(--pixel);
  transform: rotate(-6deg);
  box-shadow: 3px 3px 0 var(--ink);
}
.checking { font-weight: 800; animation: blink 1.2s steps(2) infinite; }
@keyframes blink { 50% { opacity: 0.45; } }
.doubt { margin: 0 0 12px; }

.celebrate .window-body { background: linear-gradient(180deg, var(--lime), var(--mint)); }
.celebrate h2 { font-size: 1.6rem; margin-top: 8px; }

@media (prefers-reduced-motion: reduce) {
