import { pipeline, RawImage } from "/Users/himani/projects/hackathons/Grasshopper/node_modules/@huggingface/transformers/dist/transformers.node.mjs";
const DECOYS=["a phone or computer screen","the inside of a room","a blank wall","a ceiling","a blurry photo","the ground"];
const c = await pipeline("zero-shot-image-classification","Xenova/clip-vit-base-patch32");
const quests=["a red door","a decorated auto-rickshaw","a patch of moss","a bicycle","a tiger"];
for (const [img, target] of [["door.jpg","a red door"],["door.jpg","a bicycle"],["tiger.jpg","a tiger"],["tiger.jpg","a patch of moss"]]) {
  const labels=[...new Set([target,...quests.filter(q=>q!==target),...DECOYS])];
  const r = await c(await RawImage.read(process.argv[2]+"/"+img), labels, {hypothesis_template:"a photo of {}."});
  const s = r.find(x=>x.label===target).score;
  console.log(img, "|", target, "| pass:", r[0].label===target||s>=0.3, "| score", s.toFixed(3), "| top:", r[0].label);
}
EOF
